pipeline {
  agent { label 'docker' }
  options { timeout(time: 45, unit: 'MINUTES'); timestamps(); disableConcurrentBuilds(); buildDiscarder(logRotator(numToKeepStr: '20')) }
  environment {
    IMAGE = "registry.example.com/team/app"   // placeholder
    TAG   = "${env.GIT_COMMIT.take(8)}"
    REG   = credentials('registry-creds')
  }
  stages {
    stage('Build') { steps { sh 'make build' } }
    stage('Test')  { steps { sh 'make test' } post { always { junit 'reports/*.xml' } } }
    stage('Image') { steps { sh 'docker build -t $IMAGE:$TAG .' } }
    stage('Scan')  { steps { sh 'trivy image --exit-code 1 --severity HIGH,CRITICAL $IMAGE:$TAG' } }
    stage('Push')  { steps { sh 'echo $REG_PSW | docker login registry.example.com -u $REG_USR --password-stdin && docker push $IMAGE:$TAG' } }
    stage('GitOps') {
      when { branch 'main' }
      steps {
        withCredentials([gitUsernamePassword(credentialsId: 'config-repo')]) {
          sh '''
            git clone https://git.example.com/team/app-config.git cfg
            cd cfg/overlays/dev && kustomize edit set image app=$IMAGE:$TAG
            git commit -am "app: $TAG" && git push
          '''
        }
      }
    }
    stage('Smoke') { when { branch 'main' } steps { sh 'curl -fsS https://app.example.com/health' } }
  }
  post { cleanup { cleanWs() } }
}

pipeline {
  agent {
    kubernetes {
      defaultContainer 'tools'
      yaml '''
apiVersion: v1
kind: Pod
spec:
  containers:
  - name: tools
    image: alpine/k8s:1.30.0   # placeholder: any image with kubectl and helm
    command: [sleep]
    args: [infinity]
'''
    }
  }
  environment { TAG = "${env.GIT_COMMIT.take(8)}" }
  stages {
    stage('Deploy') {
      steps {
        withKubeConfig([credentialsId: 'kubeconfig-dev', namespace: 'dev']) {
          sh 'kubectl set image deployment/app app=registry.example.com/team/app:$TAG && kubectl rollout status deployment/app --timeout=120s'
        }
      }
    }
  }
}
